import { PHONE_PRIMARY, PHONE_SECONDARY, EMAIL_SALES, GSTIN } from '@/data/contact';

export const SITE_URL = 'https://www.sumanthminerals.com';
export const SITE_NAME = 'Sumanth Minerals';

/**
 * Metadata for one page. Every page MUST set its own canonical URL and Open Graph URL:
 * Next.js inherits `alternates` and replaces (not merges) `openGraph` from the root
 * layout, so a page without these would tell Google it is a copy of the homepage.
 * Titles get " | Sumanth Minerals" from the template in the root layout.
 */
// Generated by app/opengraph-image.js. Listed explicitly because a page's own
// `openGraph` object replaces the root one, which would drop the image.
export const OG_IMAGE = {
  url: '/opengraph-image',
  width: 1200,
  height: 630,
  alt: 'Sumanth Minerals – 99.27% SiO₂ quartz lumps and grit, direct from our mine in Andhra Pradesh, India',
};

export function pageMetadata({ title, description, path, keywords }) {
  const url = `${SITE_URL}${path}`;
  return {
    title,
    description,
    ...(keywords ? { keywords } : {}),
    alternates: { canonical: url },
    openGraph: {
      title: `${title} | ${SITE_NAME}`,
      description,
      url,
      siteName: SITE_NAME,
      locale: 'en_IN',
      type: 'website',
      images: [OG_IMAGE],
    },
    twitter: { card: 'summary_large_image', title: `${title} | ${SITE_NAME}`, description, images: [OG_IMAGE.url] },
  };
}

